const mortgagePrincipal = view(Inputs.number({label: "Loan (CHF)", value: 300000, step: 1000, min: 0}));
const mortgageAnnualRate = view(Inputs.number({label: "Annual interest rate (%)", value: 1.8, step: 0.1, min: 0}));
const mortgageYears = view(Inputs.number({label: "Term (years)", value: 25, step: 1, min: 1}));

const mortgageMonthlyRate = mortgageAnnualRate / 100 / 12;
const mortgagePayments = mortgageYears * 12;
const mortgageMonthlyPayment = mortgageMonthlyRate === 0 ? mortgagePrincipal / mortgagePayments : mortgagePrincipal * mortgageMonthlyRate * (1 + mortgageMonthlyRate) ** mortgagePayments / ((1 + mortgageMonthlyRate) ** mortgagePayments - 1);

const calc = (() => {
  const r = rate / 100 / 12, n = years * 12;
  const payment = r === 0 ? principal / n : principal * r / (1 - Math.pow(1 + r, -n));
  return {r, n, payment, total: payment * n, interest: payment * n - principal};
})()

